cd /private/tmp/claude-501/-Users-guillaumeloulier-PhpstormProjects-oss-elephc--claude-worktrees-streams-csv-signature/c8dbe38f-1f79-484f-9b83-62bacab9ca56/scratchpad/uv && php -n -r '
$d="ordertest"; @mkdir($d);
foreach (["a.txt","c.log","b.md"] as $f) file_put_contents("$d/$f","x");
$n=strlen($d)+1;
function s($l,$v,$n){ echo str_pad($l,26), $v===false?"false":json_encode(array_map(fn($p)=>substr($p,$n),$v)),"\n"; }
s("brace c then a", glob("$d/{c*,a*}", GLOB_BRACE), $n);
s("brace overlapping", glob("$d/{*.txt,*}", GLOB_BRACE), $n);
s("brace nocheck mixed", glob("$d/{zz,a.txt}", GLOB_BRACE|GLOB_NOCHECK), $n);
s("plain sorted", glob("$d/*"), $n);
array_map("unlink", glob("$d/*")?:[]); @rmdir($d);
